"""Figure for notes 21.74-21.75: the reconciliation gap by price/cost bin, before and after each named adjustment; and where version D's slope sits."""
import numpy as np, pandas as pd, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt, warnings; warnings.filterwarnings("ignore")
import market1 as M, market1d as Dm
SP = M.SP; BLUE, ORANGE, AQUA, YEL, INK, MUTED, SURF, GRID, NEUT = "#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#0b0b0b", "#52514e", "#fcfcfb", "#e9e8e3", "#a8a79f"
plt.rcParams.update({"font.size": 9, "axes.edgecolor": "#c9c8c2", "axes.labelcolor": MUTED, "xtick.color": MUTED, "ytick.color": MUTED, "figure.facecolor": SURF, "axes.facecolor": SURF, "savefig.facecolor": SURF, "font.family": "DejaVu Sans"})
def clean(a):
    a.grid(True, color=GRID, linewidth=0.6); a.set_axisbelow(True); [a.spines[s].set_visible(False) for s in ("top", "right")]
def ttl(a, t): a.set_title(t, loc="left", fontsize=9.5, fontweight="bold", color=INK)
X = pd.read_parquet(f"{SP}/out/recon_fit.parquet").dropna(subset=["x_ch"]); X["g5"] = X.g4 - X.x_ch; X["day"] = X.index.tz_convert("Europe/Berlin").normalize(); edges = [-9, 0, 0.3, 0.6, 0.9, 1.1, 1.3, 1.6, 9]; labs = ["< 0", "0-0.3", "0.3-0.6", "0.6-0.9", "0.9-1.1", "1.1-1.3", "1.3-1.6", "> 1.6"]; B = pd.cut(X.r, edges, labels=False); g = X.groupby(B); days = g.day.nunique().values; x = np.arange(8)
fig, axs = plt.subplots(1, 3, figsize=(19.5, 5.2), gridspec_kw=dict(wspace=0.2, width_ratios=[1.3, 1, 1])); ax = axs[0]
STEPS = (("g2", "forecast load - scheduled generation - day-ahead net imports", NEUT, (0, (4, 2))), ("g3", "after pumping (not part of load)", YEL, "-"), ("g4", "after generation outside the schedule", ORANGE, "-"), ("g5", "after the Swiss border (not in the net position)", BLUE, "-"))
for c, lab, col, ls in STEPS: ax.plot(x, g[c].median().values, "-o", color=col, linewidth=2.2 if c == "g5" else 1.8, markersize=4.5, linestyle=ls, label=lab)
ax.axhline(0, color=INK, linewidth=0.7); ax.set_xticks(x); ax.set_xticklabels([f"{l}\n{d} days" for l, d in zip(labs, days)], fontsize=8); ax.set_xlabel("price / cost index (bin; number of days with hours in it)"); ax.set_ylabel("median gap, GW"); ax.legend(frameon=False, loc="upper left", fontsize=8); clean(ax)
m0, m5 = g.g2.median().values, g.g5.median().values; ttl(ax, f"Three named quantities remove the tilt: the gap ran from {m0[0]:+.1f} to {m0[-1]:+.1f} GW\nacross prices and is flat at about {np.median(m5):+.1f} GW afterwards")
ax = axs[1]; PARTS = (("pump", "pumping", YEL, -1.0), ("U", "generation outside the schedule", ORANGE, 1.0), ("x_ch", "imports from Switzerland", BLUE, 1.0)); w = 0.26
for k, (c, lab, col, sg) in enumerate(PARTS): ax.bar(x + (k - 1) * w, sg * g[c].median().values * (1 if c != "pump" else -1) if c != "pump" else g[c].median().values, w * 0.92, color=col, linewidth=0, label=lab)
ax.axhline(0, color=INK, linewidth=0.7); ax.set_xticks(x); ax.set_xticklabels(labs, fontsize=8); ax.set_xlabel("price / cost index"); ax.set_ylabel("median contribution to the gap, GW"); ax.legend(frameon=False, loc="upper left", fontsize=8); clean(ax); ax.grid(False, axis="x")
ttl(ax, f"Each has the predicted sign: pumping {g.pump.median().values[0]:.1f} GW at low prices,\nSwiss imports {g.x_ch.median().values[-1]:+.1f} GW at high, uncovered generation about +3")
ax = axs[2]; Q = np.load(f"{SP}/out/market1d_post.npz"); th = {k: float(np.median(Q[k])) for k in Dm.PN}; P = np.load(f"{SP}/out/market1n_post.npz"); thA = {k: float(np.median(P[k])) for k in M.PN}; L_, c_ = 90.0, 70.0; pg = np.linspace(-20, 200, 441); rr = pg / L_; gT, gX, gC = Dm.curves(th, pg, np.full_like(pg, L_), np.full_like(pg, c_)); d = lambda v: np.gradient(v, pg); sA = d(M.supply(thA, pg, np.full_like(pg, L_), np.full_like(pg, c_)))
ax.stackplot(rr, d(gT), d(gX), d(gC), colors=[NEUT, AQUA, ORANGE], labels=["D: dispatchable block", "D: day-ahead imports (no Swiss border)", "D: closing block (the gap)"], linewidth=0, alpha=0.9); ax.plot(rr, sA, color=INK, linewidth=1.8, label="A: total (imports = all borders, realised)"); ax.set_xlim(-0.2, 2.2); ax.set_ylim(0, None); ax.set_xlabel("price / cost index (cost index 90 EUR/MWh)"); ax.set_ylabel("slope of supply, GW per EUR/MWh"); ax.legend(frameon=False, loc="upper right", fontsize=8); clean(ax)
sh = np.interp([0.6, 1.0, 1.4], rr, d(gC) / (d(gT) + d(gX) + d(gC))); ttl(ax, f"In version D the gap carries {sh[0]:.0%} / {sh[1]:.0%} / {sh[2]:.0%} of the supply slope at\nprice/cost 0.6 / 1.0 / 1.4: pumping and the Swiss border in disguise")
fig.suptitle("Tracing the day-ahead reconciliation gap to its sources (fitting period, Mar 2024 - Nov 2025, hourly)", x=0.06, ha="left", fontsize=11, fontweight="bold", color=INK, y=1.03); fig.savefig(f"{SP}/out/recon_gap.png", dpi=100, bbox_inches="tight")
print("medians g5:", np.round(m5, 2), "| sd of g2, g3, g4, g5:", [round(float(X[c].std()), 2) for c in ("g2", "g3", "g4", "g5")], "| closing share of D slope at r 0.3/0.6/1.0/1.4:", np.round(np.interp([0.3, 0.6, 1.0, 1.4], rr, d(gC) / (d(gT) + d(gX) + d(gC))), 2), "| D total slope:", np.round(np.interp([0.3, 0.6, 1.0, 1.4], rr, d(gT) + d(gX) + d(gC)), 2), "D without closing:", np.round(np.interp([0.3, 0.6, 1.0, 1.4], rr, d(gT) + d(gX)), 2), "A total:", np.round(np.interp([0.3, 0.6, 1.0, 1.4], rr, sA), 2))
print("slope of the Swiss exchange and of pumping in price, empirical (binned, GW per unit of price/cost): x_ch between r 1.0 and 1.5:", round(float((g.x_ch.median().values[6] - g.x_ch.median().values[4]) / 0.45), 2), "pump between r 0.15 and 1.0:", round(float((g.pump.median().values[4] - g.pump.median().values[1]) / 0.85), 2))
